  "summary": "GMMTV 年度旗舰粉丝节 LOVE OUT LOUD FAN FEST 2026: HEART RACE 于5/22-24在曼谷 Impact Arena 举办，集结12对CP(PondPhuwin、JoongDunk、EarthMix、GeminiFourth等)，以F1赛车为主题，每对CP对应一款车队。含 Sound Check、Hi-Session 等粉丝互动，票价2000-7900泰铢，TTM LIVE 全球直播。是2026泰国CP周边消费最高峰事件。（印选 11-05 热点重排上架：库内真实历史热点复用，非新研究。）（印选 11-08 热点重排上架：库内真实历史热点复用，非新研究。）（印选 11-09 热点重排上架：库内真实历史热点复用，非新研究。）",
